import"./chunk-VC46IEJQ.js";var a=(t,r)=>({en:t,zh:r}),e=(t,r,o,n,s,h,d,l,i)=>({name:a(...t),desc:a(...r),tour:a(...o),...i?{spoiler:a(...i)}:{},source:{confidence:n,refs:s,book:a(...h),unknown:a(...d),interpretation:a(...l)}}),c={id:"meereen",intro:{en:"The largest and proudest of the Slaver cities, built of many-coloured brick where the Skahazadhan meets Slaver's Bay. Its stepped pyramids house the old families, and the Great Pyramid towers over them all.",zh:"\u5974\u96B6\u57CE\u90A6\u4E2D\u6700\u5927\u3001\u4E5F\u6700\u9A84\u50B2\u7684\u4E00\u5EA7\uFF0C\u4EE5\u4E94\u5F69\u7816\u77F3\u5EFA\u5728\u65AF\u5361\u54C8\u624E\u4E39\u6CB3\u6C47\u5165\u5974\u96B6\u6E7E\u4E4B\u5904\u3002\u9636\u68AF\u91D1\u5B57\u5854\u91CC\u4F4F\u7740\u53E4\u8001\u5BB6\u65CF\uFF0C\u5927\u91D1\u5B57\u5854\u5219\u51CC\u9A7E\u4E8E\u4E00\u5207\u4E4B\u4E0A\u3002"},notes:{en:"From the books: many-coloured brick, the Great Pyramid with a bronze harpy on top and apartments and a terrace garden at its apex, the pyramids of other houses (Hazkar, Loraq), the fighting pits with Daznak's Pit the greatest, the golden-domed Temple of the Graces, the Plaza of Purification with its own bronze harpy, the Skahazadhan and the brick sewers that drain into it. Invented here: the plan, scale, walls and gates, the number and placement of pyramids, the river's course, the harbour and every architectural detail. Pyramid heights are scaled well down from the book's figures, and the pit cutaway is an interpretation.",zh:"\u4E66\u4E2D\u53EF\u636E\uFF1A\u4E94\u5F69\u7816\u77F3\uFF1B\u9876\u7ACB\u9752\u94DC\u9E70\u8EAB\u5973\u5996\u3001\u5854\u9876\u6709\u5C45\u6240\u4E0E\u9732\u53F0\u82B1\u56ED\u7684\u5927\u91D1\u5B57\u5854\uFF1B\u5176\u4ED6\u5BB6\u65CF\u7684\u91D1\u5B57\u5854\uFF08\u54C8\u5179\u5361\u3001\u6D1B\u62C9\u514B\uFF09\uFF1B\u4EE5\u8FBE\u5179\u7EB3\u514B\u7ADE\u6280\u573A\u4E3A\u6700\u5927\u7684\u8BF8\u591A\u89D2\u6597\u573A\uFF1B\u91D1\u8272\u5706\u9876\u7684\u7F8E\u60E0\u795E\u5E99\uFF1B\u53E6\u7ACB\u4E00\u5C0A\u9752\u94DC\u9E70\u8EAB\u5973\u5996\u7684\u51C0\u5316\u5E7F\u573A\uFF1B\u65AF\u5361\u54C8\u624E\u4E39\u6CB3\u53CA\u901A\u5165\u6CB3\u4E2D\u7684\u7816\u780C\u4E0B\u6C34\u9053\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u57CE\u5E02\u5E73\u9762\u3001\u6BD4\u4F8B\u3001\u57CE\u5899\u4E0E\u57CE\u95E8\u3001\u91D1\u5B57\u5854\u7684\u6570\u91CF\u4E0E\u4F4D\u7F6E\u3001\u6CB3\u9053\u8D70\u5411\u3001\u6E2F\u53E3\u53CA\u5168\u90E8\u5EFA\u7B51\u7EC6\u8282\u3002\u91D1\u5B57\u5854\u9AD8\u5EA6\u8F83\u4E66\u4E2D\u6570\u5B57\u5927\u5E45\u7F29\u5C0F\uFF0C\u7ADE\u6280\u573A\u5256\u9762\u4EA6\u5C5E\u63A8\u60F3\u3002"},tour:["city-walls","harbour","great-pyramid","harpy-statue","apex-garden","daznak-pit","temple-of-graces","plaza-of-purification","pyramid-of-hazkar","skahazadhan"],sources:[{ref:"adwd",checked:"memory",note:a("Meereen is the main setting of Daenerys's chapters in A Dance with Dragons; pyramids, pits, temple and plaza recalled, not re-read.","\u5F25\u6797\u662F\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\u4E39\u59AE\u8389\u4E1D\u7AE0\u8282\u7684\u4E3B\u8981\u821E\u53F0\uFF1B\u91D1\u5B57\u5854\u3001\u89D2\u6597\u573A\u3001\u795E\u5E99\u4E0E\u5E7F\u573A\u5747\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002")},{ref:"asos",checked:"memory",note:a("The first sight of the city, its walls and the entry through the sewers, from A Storm of Swords.","\u57CE\u5E02\u521D\u8C8C\u3001\u57CE\u5899\u4EE5\u53CA\u7ECF\u7531\u4E0B\u6C34\u9053\u5165\u57CE\u4E00\u8282\uFF0C\u89C1\u4E8E\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\u3002")},{ref:"awoiaf",checked:"search-snippet",note:a("Search summaries of the wiki: Daznak's Pit and the golden-domed Temple of the Graces both west of the Great Pyramid (the temple visible from its terrace), a great bronze harpy in the Plaza of Purification separate from the one on the pyramid, and the Hazkar and Loraq pyramids. The wiki notes that part of its Meereen material draws on an unpublished Winds of Winter sample chapter, which is not used here. Pages could not be fetched.","\u7ECF\u7EF4\u57FA\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF1A\u8FBE\u5179\u7EB3\u514B\u7ADE\u6280\u573A\u4E0E\u91D1\u8272\u5706\u9876\u7684\u7F8E\u60E0\u795E\u5E99\u90FD\u5728\u5927\u91D1\u5B57\u5854\u4EE5\u897F\uFF08\u4ECE\u5854\u9876\u9732\u53F0\u53EF\u671B\u89C1\u795E\u5E99\uFF09\uFF1B\u51C0\u5316\u5E7F\u573A\u53E6\u6709\u4E00\u5C0A\u5DE8\u5927\u7684\u9752\u94DC\u9E70\u8EAB\u5973\u5996\uFF0C\u4E0E\u5854\u9876\u90A3\u5C0A\u4E0D\u540C\uFF1B\u4EE5\u53CA\u54C8\u5179\u5361\u4E0E\u6D1B\u62C9\u514B\u7684\u91D1\u5B57\u5854\u3002\u7EF4\u57FA\u6CE8\u660E\u5176\u90E8\u5206\u5F25\u6797\u8D44\u6599\u51FA\u81EA\u5C1A\u672A\u51FA\u7248\u7684\u300A\u51DB\u51AC\u7684\u5BD2\u98CE\u300B\u8BD5\u8BFB\u7AE0\u8282\uFF0C\u672C\u573A\u666F\u4E0D\u4E88\u91C7\u7528\u3002\u9875\u9762\u672C\u8EAB\u65E0\u6CD5\u6253\u5F00\u3002")},{ref:"twoiaf",checked:"not-accessed",note:a("The city's founding and history were not consulted.","\u672A\u67E5\u9605\u57CE\u5E02\u7684\u5EFA\u7ACB\u4E0E\u5386\u53F2\u3002")}],landmarks:{"great-pyramid":e(["Great Pyramid","\u5927\u91D1\u5B57\u5854"],["The immense stepped pyramid of many-coloured brick at the heart of Meereen, far taller than anything around it.","\u5F25\u6797\u4E2D\u5FC3\u90A3\u5EA7\u4E94\u5F69\u7816\u780C\u7684\u5DE8\u5927\u9636\u68AF\u91D1\u5B57\u5854\uFF0C\u8FDC\u9AD8\u4E8E\u5468\u56F4\u7684\u4E00\u5207\u3002"],["Everything in Meereen is measured against the Great Pyramid and its bands of coloured brick.","\u5F25\u6797\u7684\u4E00\u5207\u90FD\u4EE5\u8FD9\u5EA7\u5F69\u7816\u5C42\u53E0\u7684\u5927\u91D1\u5B57\u5854\u4E3A\u5C3A\u5EA6\u3002"],"high",["asos","adwd"],["The largest pyramid in the city, with apartments and a terrace garden at its top.","\u57CE\u4E2D\u6700\u5927\u7684\u91D1\u5B57\u5854\uFF0C\u5854\u9876\u6709\u5C45\u6240\u4E0E\u9732\u53F0\u82B1\u56ED\u3002"],["Its exact form, number of tiers and colour pattern.","\u786E\u5207\u5F62\u5236\u3001\u5C42\u6570\u4E0E\u914D\u8272\u3002"],["Nine tiers, scaled far down so the whole city fits one scene; colours alternate by tier.","\u4E5D\u5C42\uFF0C\u4E3A\u4F7F\u5168\u57CE\u7EB3\u5165\u4E00\u4E2A\u573A\u666F\u800C\u5927\u5E45\u7F29\u5C0F\uFF1B\u5404\u5C42\u989C\u8272\u4EA4\u66FF\u3002"]),"harpy-statue":e(["Bronze Harpy","\u9752\u94DC\u9E70\u8EAB\u5973\u5996"],["A huge bronze harpy on the apex of the Great Pyramid, emblem of Old Ghis.","\u5927\u91D1\u5B57\u5854\u9876\u4E0A\u5DE8\u5927\u7684\u9752\u94DC\u9E70\u8EAB\u5973\u5996\uFF0C\u53E4\u5409\u65AF\u7684\u5FBD\u8BB0\u3002"],["From the summit, the bronze harpy of Ghis watches over the city.","\u5409\u65AF\u7684\u9752\u94DC\u9E70\u8EAB\u5973\u5996\u4ECE\u5854\u9876\u4FEF\u77B0\u5168\u57CE\u3002"],"high",["asos","awoiaf"],["A great bronze harpy stands atop the Great Pyramid when Daenerys arrives.","\u4E39\u59AE\u8389\u4E1D\u5230\u6765\u65F6\uFF0C\u5927\u91D1\u5B57\u5854\u9876\u4E0A\u7ACB\u7740\u4E00\u5C0A\u5DE8\u5927\u7684\u9752\u94DC\u9E70\u8EAB\u5973\u5996\u3002"],["Its exact size and pose.","\u786E\u5207\u5927\u5C0F\u4E0E\u59FF\u6001\u3002"],["A winged, clawed figure on a plinth; the pose is invented.","\u7ACB\u4E8E\u57FA\u5EA7\u4E0A\u7684\u6709\u7FFC\u5E26\u722A\u4EBA\u5F62\uFF1B\u59FF\u6001\u4E3A\u81EA\u62DF\u3002"],["After taking the city, Daenerys has the harpy pulled down and makes the pyramid her seat.","\u653B\u4E0B\u5F25\u6797\u540E\uFF0C\u4E39\u59AE\u8389\u4E1D\u4E0B\u4EE4\u63A8\u5012\u8FD9\u5C0A\u9E70\u8EAB\u5973\u5996\uFF0C\u5E76\u4EE5\u5927\u91D1\u5B57\u5854\u4E3A\u5C45\u6240\u3002"]),"apex-garden":e(["Summit Terrace","\u5854\u9876\u82B1\u56ED"],["A garden terrace with a pool, trees and pavilions near the top of the Great Pyramid.","\u5927\u91D1\u5B57\u5854\u9876\u90E8\u7684\u9732\u53F0\u82B1\u56ED\uFF0C\u6709\u6C34\u6C60\u3001\u6811\u6728\u4E0E\u4EAD\u9601\u3002"],["High above the city lie the queen's rooms, a terrace garden and a bathing pool.","\u5973\u738B\u7684\u5C45\u5BA4\u3001\u9732\u53F0\u82B1\u56ED\u4E0E\u6D74\u6C60\uFF0C\u9AD8\u60AC\u5728\u5168\u57CE\u4E4B\u4E0A\u3002"],"high",["adwd","awoiaf"],["Apartments and a terrace garden with trees and a pool at the top of the Great Pyramid.","\u5927\u91D1\u5B57\u5854\u9876\u90E8\u6709\u5C45\u5BA4\uFF0C\u4EE5\u53CA\u79CD\u7740\u6811\u6728\u3001\u8BBE\u6709\u6C34\u6C60\u7684\u9732\u53F0\u82B1\u56ED\u3002"],["The layout of rooms and plantings.","\u623F\u95F4\u4E0E\u690D\u683D\u7684\u5E03\u5C40\u3002"],["One pavilion, a pool and a few palms on a plastered roof terrace.","\u62B9\u7070\u7684\u5C4B\u9876\u9732\u53F0\u4E0A\uFF0C\u4E00\u5EA7\u4EAD\u9601\u3001\u4E00\u6C60\u6E05\u6C34\u4E0E\u51E0\u682A\u68D5\u6988\u3002"]),"pyramid-of-hazkar":e(["Pyramid of Hazkar","\u54C8\u5179\u5361\u91D1\u5B57\u5854"],["The pyramid of an old Meereenese house, drawn here in red and yellow stripes in the south-east.","\u5F25\u6797\u4E00\u4E2A\u53E4\u8001\u5BB6\u65CF\u7684\u91D1\u5B57\u5854\uFF0C\u672C\u573A\u666F\u753B\u4F5C\u7EA2\u9EC4\u6761\u7EB9\uFF0C\u7F6E\u4E8E\u4E1C\u5357\u3002"],["The great families each live in a pyramid of their own.","\u5404\u5927\u5BB6\u65CF\u5404\u5C45\u4E00\u5EA7\u91D1\u5B57\u5854\u3002"],"medium",["adwd","awoiaf"],["A pyramid of Hazkar is named in the city.","\u4E66\u4E2D\u63D0\u5230\u57CE\u4E2D\u6709\u54C8\u5179\u5361\u91D1\u5B57\u5854\u3002"],["Its look and position.","\u5916\u89C2\u4E0E\u4F4D\u7F6E\u3002"],["Seven tiers in alternating red and yellow, south-east of the plaza; invented.","\u4E03\u5C42\u7EA2\u9EC4\u76F8\u95F4\uFF0C\u7F6E\u4E8E\u5E7F\u573A\u4E1C\u5357\uFF1B\u4E3A\u81EA\u62DF\u3002"]),"pyramid-of-loraq":e(["Pyramid of Loraq","\u6D1B\u62C9\u514B\u91D1\u5B57\u5854"],["The pyramid of House Loraq, drawn here in blue and cream in the south-west.","\u6D1B\u62C9\u514B\u5BB6\u65CF\u7684\u91D1\u5B57\u5854\uFF0C\u672C\u573A\u666F\u753B\u4F5C\u84DD\u767D\u76F8\u95F4\uFF0C\u7F6E\u4E8E\u897F\u5357\u3002"],["House Loraq, one of the oldest families, keeps its own pyramid.","\u6700\u53E4\u8001\u7684\u5BB6\u65CF\u4E4B\u4E00\u6D1B\u62C9\u514B\u5BB6\u65CF\uFF0C\u62E5\u6709\u81EA\u5DF1\u7684\u91D1\u5B57\u5854\u3002"],"medium",["adwd","awoiaf"],["House Loraq is a prominent old family with a pyramid in the city.","\u6D1B\u62C9\u514B\u5BB6\u65CF\u662F\u57CE\u4E2D\u663E\u8D6B\u7684\u53E4\u8001\u5BB6\u65CF\uFF0C\u62E5\u6709\u4E00\u5EA7\u91D1\u5B57\u5854\u3002"],["Its look and position.","\u5916\u89C2\u4E0E\u4F4D\u7F6E\u3002"],["Form, colour and position are entirely invented.","\u5F62\u5236\u3001\u989C\u8272\u4E0E\u4F4D\u7F6E\u5B8C\u5168\u4E3A\u81EA\u62DF\u3002"]),"daznak-pit":e(["Daznak's Pit","\u8FBE\u5179\u7EB3\u514B\u7ADE\u6280\u573A"],["The greatest of Meereen's fighting pits, a ringed brick bowl west of the Great Pyramid. A cutaway shows the seats and sand.","\u5F25\u6797\u6700\u5927\u7684\u89D2\u6597\u573A\uFF0C\u4F4D\u4E8E\u5927\u91D1\u5B57\u5854\u4EE5\u897F\uFF0C\u662F\u4E00\u5EA7\u73AF\u5F62\u7816\u780C\u770B\u53F0\u3002\u53EF\u6253\u5F00\u5256\u9762\u67E5\u770B\u5EA7\u5E2D\u4E0E\u6C99\u5730\u3002"],["Daznak's Pit is the greatest of the city's arenas, its tiers climbing to the rim.","\u8FBE\u5179\u7EB3\u514B\u7ADE\u6280\u573A\u662F\u57CE\u4E2D\u6700\u5927\u7684\u89D2\u6597\u573A\uFF0C\u5EA7\u5E2D\u5C42\u5C42\u5347\u5411\u573A\u6CBF\u3002"],"medium",["adwd","awoiaf"],["The largest fighting pit, west of the Great Pyramid, with tiered seating for great crowds.","\u6700\u5927\u7684\u89D2\u6597\u573A\uFF0C\u5728\u5927\u91D1\u5B57\u5854\u4EE5\u897F\uFF0C\u5C42\u5C42\u5EA7\u5E2D\u53EF\u5BB9\u7EB3\u5927\u6279\u89C2\u4F17\u3002"],["Its size, number of tiers and interior.","\u89C4\u6A21\u3001\u5C42\u6570\u4E0E\u5185\u90E8\u7ED3\u6784\u3002"],["Eleven tiers, a royal box, tunnels and a sand floor; all interior detail is invented.","\u5341\u4E00\u5C42\u5EA7\u5E2D\u3001\u738B\u5BA4\u770B\u53F0\u3001\u901A\u9053\u4E0E\u6C99\u5730\uFF1B\u5185\u90E8\u7EC6\u8282\u5747\u4E3A\u81EA\u62DF\u3002"],["At the reopening games here, Drogon descends on the sands and Daenerys flies off on his back.","\u7ADE\u6280\u573A\u91CD\u5F00\u4E4B\u65E5\uFF0C\u5353\u803F\u4ECE\u5929\u800C\u964D\u843D\u5728\u6C99\u5730\u4E0A\uFF0C\u4E39\u59AE\u8389\u4E1D\u9A91\u7740\u5B83\u98DE\u79BB\u3002"]),"temple-of-graces":e(["Temple of the Graces","\u7F8E\u60E0\u795E\u5E99"],["A great temple crowned with golden domes, home of the priestesses called the Graces.","\u4E00\u5EA7\u91D1\u8272\u5706\u9876\u7684\u5B8F\u4F1F\u795E\u5E99\uFF0C\u540D\u4E3A\u201C\u7F8E\u60E0\u201D\u7684\u5973\u796D\u53F8\u4EEC\u5C45\u4E8E\u5176\u4E2D\u3002"],["Golden domes rise among the brick: the temple of the Graces, seen from the queen's terrace.","\u91D1\u8272\u5706\u9876\u5728\u7816\u8272\u4E2D\u5347\u8D77\uFF1A\u8FD9\u4FBF\u662F\u4ECE\u5973\u738B\u9732\u53F0\u4E0A\u671B\u89C1\u7684\u7F8E\u60E0\u795E\u5E99\u3002"],"high",["adwd","awoiaf"],["A huge temple with golden domes, west of the Great Pyramid and visible from its terrace.","\u4E00\u5EA7\u91D1\u8272\u5706\u9876\u7684\u5DE8\u5927\u795E\u5E99\uFF0C\u5728\u5927\u91D1\u5B57\u5854\u4EE5\u897F\uFF0C\u4ECE\u5854\u9876\u9732\u53F0\u53EF\u4EE5\u671B\u89C1\u3002"],["Its plan and interior.","\u5E73\u9762\u4E0E\u5185\u90E8\u5E03\u7F6E\u3002"],["A colonnaded platform with a central domed hall; the shape is invented.","\u5E26\u67F1\u5ECA\u7684\u53F0\u57FA\uFF0C\u4E2D\u592E\u4E3A\u5706\u9876\u5927\u6BBF\uFF1B\u5F62\u5236\u4E3A\u81EA\u62DF\u3002"]),"plaza-of-purification":e(["Plaza of Purification","\u51C0\u5316\u5E7F\u573A"],["A paved square with a great bronze harpy of its own.","\u4E00\u5EA7\u94FA\u77F3\u5E7F\u573A\uFF0C\u53E6\u7ACB\u7740\u4E00\u5C0A\u5DE8\u5927\u7684\u9752\u94DC\u9E70\u8EAB\u5973\u5996\u3002"],["The plaza keeps its own bronze harpy; a sculptor offers to give it the queen's face.","\u5E7F\u573A\u53E6\u6709\u4E00\u5C0A\u9752\u94DC\u9E70\u8EAB\u5973\u5996\uFF1B\u66FE\u6709\u96D5\u523B\u5E08\u63D0\u51FA\u628A\u5B83\u7684\u5934\u6362\u6210\u5973\u738B\u7684\u6A21\u6837\u3002"],"medium",["adwd","awoiaf"],["A plaza with a great bronze harpy; Daenerys refuses a sculptor's offer to recast its head in her likeness.","\u4E00\u5EA7\u7ACB\u6709\u5DE8\u5927\u9752\u94DC\u9E70\u8EAB\u5973\u5996\u7684\u5E7F\u573A\uFF1B\u4E39\u59AE\u8389\u4E1D\u62D2\u7EDD\u4E86\u96D5\u523B\u5E08\u6309\u5979\u7684\u5BB9\u8C8C\u91CD\u94F8\u96D5\u50CF\u5934\u90E8\u7684\u63D0\u8BAE\u3002"],["Its size and location.","\u89C4\u6A21\u4E0E\u4F4D\u7F6E\u3002"],["Placed east of the Great Pyramid; paving, posts and fountain are invented.","\u7F6E\u4E8E\u5927\u91D1\u5B57\u5854\u4EE5\u4E1C\uFF1B\u94FA\u5730\u3001\u7ACB\u67F1\u4E0E\u55B7\u6CC9\u5747\u4E3A\u81EA\u62DF\u3002"]),"city-walls":e(["City Walls","\u57CE\u5899"],["Thick walls of many-coloured brick with great towers and gates.","\u4E94\u5F69\u7816\u780C\u7684\u539A\u91CD\u57CE\u5899\uFF0C\u914D\u6709\u9AD8\u5927\u7684\u5854\u697C\u4E0E\u57CE\u95E8\u3002"],["Thick walls of coloured brick ring the largest city on the bay.","\u4E94\u5F69\u7816\u780C\u7684\u539A\u5899\uFF0C\u73AF\u7ED5\u7740\u6D77\u6E7E\u7554\u6700\u5927\u7684\u57CE\u5E02\u3002"],"medium",["asos","adwd"],["Meereen is walled and gated; Daenerys besieges it before taking it.","\u5F25\u6797\u6709\u57CE\u5899\u4E0E\u57CE\u95E8\uFF1B\u4E39\u59AE\u8389\u4E1D\u56F4\u57CE\u4E4B\u540E\u5C06\u5176\u653B\u4E0B\u3002"],["Height, thickness, number of towers and gates.","\u9AD8\u5EA6\u3001\u539A\u5EA6\u3001\u5854\u697C\u4E0E\u57CE\u95E8\u6570\u91CF\u3002"],["A large ring of 36 segments, one colour each, with four gates.","\u7531\u4E09\u5341\u516D\u6BB5\u7EC4\u6210\u7684\u5927\u73AF\uFF0C\u6BCF\u6BB5\u4E00\u8272\uFF0C\u8BBE\u56DB\u5EA7\u57CE\u95E8\u3002"]),harbour:e(["Harbour","\u6D77\u6E2F"],["A long quay with seven piers on Slaver's Bay, crowded with cogs and galleys.","\u5974\u96B6\u6E7E\u7554\u4E00\u9053\u957F\u957F\u7684\u7801\u5934\uFF0C\u4E03\u5EA7\u6808\u6865\u8FB9\u6324\u6EE1\u67EF\u514B\u8239\u4E0E\u6868\u5E06\u8239\u3002"],["The largest of the Slaver cities looks out across the bay.","\u5974\u96B6\u57CE\u90A6\u4E2D\u6700\u5927\u7684\u4E00\u5EA7\uFF0C\u9762\u671D\u6D77\u6E7E\u3002"],"medium",["adwd"],["Meereen lies on the bay and has a harbour used by trading ships and war fleets.","\u5F25\u6797\u6FD2\u4E34\u6D77\u6E7E\uFF0C\u6E2F\u53E3\u6709\u5546\u8239\u5F80\u6765\uFF0C\u4E5F\u6709\u8230\u961F\u51FA\u6CA1\u3002"],["Layout and number of docks.","\u5E03\u5C40\u4E0E\u7801\u5934\u6570\u91CF\u3002"],["A straight quay with piers and two jetties; invented.","\u4E00\u9053\u7B14\u76F4\u7801\u5934\uFF0C\u52A0\u4E0A\u6808\u6865\u4E0E\u4E24\u9053\u7A81\u5824\uFF1B\u5747\u4E3A\u81EA\u62DF\u3002"]),skahazadhan:e(["Skahazadhan","\u65AF\u5361\u54C8\u624E\u4E39\u6CB3"],["The river that runs past the city into the bay, with barges and green fields.","\u6D41\u7ECF\u57CE\u8FB9\u3001\u6C47\u5165\u6D77\u6E7E\u7684\u6CB3\u6D41\uFF0C\u6CB3\u4E0A\u6709\u9A73\u8239\uFF0C\u5CB8\u8FB9\u662F\u7EFF\u7530\u3002"],["The Skahazadhan brings water and green fields to a dusty coast.","\u65AF\u5361\u54C8\u624E\u4E39\u6CB3\u4E3A\u5E72\u71E5\u7684\u6D77\u5CB8\u5E26\u6765\u6C34\u6E90\u4E0E\u7EFF\u91CE\u3002"],"high",["asos","adwd"],["Meereen stands at the Skahazadhan's mouth; the city's sewers drain into it.","\u5F25\u6797\u5750\u843D\u5728\u65AF\u5361\u54C8\u624E\u4E39\u6CB3\u53E3\uFF1B\u57CE\u4E2D\u4E0B\u6C34\u9053\u6392\u5165\u6CB3\u4E2D\u3002"],["The river's exact course and width near the city.","\u6CB3\u6D41\u5728\u57CE\u8FB9\u7684\u786E\u5207\u8D70\u5411\u4E0E\u5BBD\u5EA6\u3002"],["A winding river on the east side; width and bends are invented.","\u57CE\u4E1C\u4E00\u6761\u873F\u8712\u7684\u6CB3\uFF1B\u5BBD\u5EA6\u4E0E\u5F2F\u9053\u5747\u4E3A\u81EA\u62DF\u3002"]),"lower-city":e(["Lower City","\u4E0B\u57CE"],["Flat-roofed brick houses in every colour, markets and winding lanes between the pyramids.","\u4E94\u989C\u516D\u8272\u7684\u5E73\u9876\u7816\u5C4B\u3001\u96C6\u5E02\uFF0C\u4EE5\u53CA\u91D1\u5B57\u5854\u4E4B\u95F4\u66F2\u6298\u7684\u5C0F\u5DF7\u3002"],["Between the pyramids lies the ordinary city, in every colour of brick.","\u91D1\u5B57\u5854\u4E4B\u95F4\u4FBF\u662F\u5BFB\u5E38\u5E02\u4E95\uFF0C\u7816\u8272\u4E94\u5F69\u6591\u6593\u3002"],"low",["adwd"],["The ordinary city is not mapped in detail.","\u5BFB\u5E38\u8857\u533A\u5E76\u65E0\u8BE6\u7EC6\u63CF\u7ED8\u3002"],["Everything about the ordinary quarters.","\u5E73\u6C11\u8857\u533A\u7684\u4E00\u5207\u3002"],["Random houses in coloured brick, plus a small market near the east road.","\u968F\u673A\u5E03\u7F6E\u7684\u5F69\u7816\u623F\u5C4B\uFF0C\u53E6\u5728\u4E1C\u8DEF\u65C1\u8BBE\u4E00\u5904\u5C0F\u5E02\u573A\u3002"]),"sewer-outfalls":e(["Brick Sewers","\u7816\u780C\u4E0B\u6C34\u9053"],["Large brick outfalls that carry the city's waste into the Skahazadhan.","\u5927\u578B\u7816\u780C\u6392\u6C34\u53E3\uFF0C\u628A\u57CE\u4E2D\u6C61\u6C34\u6392\u5165\u65AF\u5361\u54C8\u624E\u4E39\u6CB3\u3002"],["Great brick sewers empty into the river. Daenerys's men once crept in this way.","\u5B8F\u5927\u7684\u7816\u780C\u4E0B\u6C34\u9053\u901A\u5165\u6CB3\u4E2D\u3002\u4E39\u59AE\u8389\u4E1D\u7684\u4EBA\u9A6C\u66FE\u7531\u6B64\u6F5C\u5165\u57CE\u4E2D\u3002"],"high",["asos","awoiaf"],["Meereen's brick sewers drain into the Skahazadhan; Daenerys's fighters enter the city through them during the siege.","\u5F25\u6797\u7684\u7816\u780C\u4E0B\u6C34\u9053\u6392\u5165\u65AF\u5361\u54C8\u624E\u4E39\u6CB3\uFF1B\u56F4\u57CE\u671F\u95F4\uFF0C\u4E39\u59AE\u8389\u4E1D\u7684\u6218\u58EB\u7ECF\u7531\u4E0B\u6C34\u9053\u6F5C\u5165\u57CE\u5185\u3002"],["Their routes and number.","\u8D70\u5411\u4E0E\u6570\u91CF\u3002"],["Three small outfalls, as a symbol only.","\u4E09\u5904\u5C0F\u6392\u6C34\u53E3\uFF0C\u4EC5\u4F5C\u8C61\u5F81\u3002"])}};export{c as default};
